     public function show(Request $request, CashRegister $cashRegister): JsonResponse
     {
         $this->ensureBranchAccess($request, $cashRegister->branch_id);
         abort_unless(
             ! $request->user()->hasRole('cajero')
                 || $request->user()->hasRole('supervisor')
                 || $request->user()->hasRole('admin')
                 || $cashRegister->users()->whereKey($request->user()->id)->exists(),
             403,
             'No tienes acceso a esta caja.',
         );

         return response()->json($cashRegister->load('branch:id,name,code', 'users:id,name,email'));
     }

     public function update(Request $request, CashRegister $cashRegister): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'branch_id' => ['sometimes', 'required', 'integer', 'exists:branches,id'],
             'name' => ['sometimes', 'required', 'string', 'max:255'],
             'code' => [
                 'sometimes',
                 'required',
                 'string',
                 'max:255',
                 Rule::unique('cash_registers', 'code')
                     ->where('branch_id', $request->input('branch_id', $cashRegister->branch_id))
                     ->ignore($cashRegister->id),
             ],
             'is_active' => ['sometimes', 'boolean'],
             'user_ids' => ['sometimes', 'array'],
             'user_ids.*' => ['integer', 'distinct', 'exists:users,id'],
         ]);

         if (array_key_exists('user_ids', $data)) {
             $cashRegister->users()->sync($data['user_ids']);
             unset($data['user_ids']);
         }

         $cashRegister->update($data);

         return response()->json($cashRegister->load('branch:id,name,code', 'users:id,name,email'));
     }

     private function ensureAdmin(Request $request): void
     {
         abort_unless($request->user()->hasRole('admin'), 403, 'Se requiere el rol admin.');
     }

     private function ensureBranchAccess(Request $request, int $branchId): void
     {
         abort_unless(
             $request->user()->hasRole('admin') || in_array($branchId, $request->user()->accessibleBranchIds()),
             403,
             'No tienes acceso a esta sucursal.',
         );
     }
 }

