 namespace App\Http\Controllers\Api;

 use App\Http\Controllers\Controller;
 use App\Models\User;
 use Illuminate\Http\JsonResponse;
 use Illuminate\Http\Request;
 use Illuminate\Validation\Rule;

 class UserController extends Controller
 {
     private const ROLES = ['admin', 'supervisor', 'cajero'];

     public function index(Request $request): JsonResponse
     {
         $this->ensureAdmin($request);

         $users = User::query()->with('roles')->orderBy('name')->get()
             ->map(fn (User $user) => $this->userPayload($user));

         return response()->json($users);
     }

     public function store(Request $request): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'name' => ['required', 'string', 'max:255'],
             'email' => ['required', 'email', 'max:255', 'unique:users,email'],
             'password' => ['required', 'string', 'min:12', 'confirmed'],
             'roles' => ['required', 'array', 'min:1'],
             'roles.*' => ['required', 'string', 'distinct', Rule::in(self::ROLES)],
         ]);

         $roles = $data['roles'];
         unset($data['roles'], $data['password_confirmation']);

         $user = User::create($data);
         $user->syncRoles($roles);

         return response()->json($this->userPayload($user), 201);
     }

     public function update(Request $request, User $user): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'name' => ['sometimes', 'required', 'string', 'max:255'],
             'email' => ['sometimes', 'required', 'email', 'max:255', Rule::unique('users', 'email')->ignore($user->id)],
             'password' => ['sometimes', 'required', 'string', 'min:12', 'confirmed'],
             'roles' => ['sometimes', 'required', 'array', 'min:1'],
             'roles.*' => ['required', 'string', 'distinct', Rule::in(self::ROLES)],
         ]);

         if (array_key_exists('roles', $data)) {
             $roles = $data['roles'];
             unset($data['roles']);

             if ($user->hasRole('admin') && ! in_array('admin', $roles) && User::role('admin')->count() <= 1) {
                 return response()->json(['message' => 'No se puede quitar el último administrador.'], 422);
             }

             $user->syncRoles($roles);
         }

         unset($data['password_confirmation']);
         $user->fill($data)->save();

         return response()->json($this->userPayload($user));
     }

     private function userPayload(User $user): array
     {
         return [
             'id' => $user->id,
             'name' => $user->name,
             'email' => $user->email,
             'roles' => $user->getRoleNames(),
         ];
     }

     private function ensureAdmin(Request $request): void
     {
         abort_unless($request->user()->hasRole('admin'), 403, 'Se requiere el rol admin.');
     }
 }

