 export type User = {
   id: number
   name: string
   username: string
   email: string
   roles: string[]
 }

 export class ApiError extends Error {
   status: number

   constructor(status: number, message: string) {
     super(message)
     this.status = status
   }
 }

 export async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
   let response: Response
   try {
     response = await fetch(`/api${path}`, {
       ...options,
       headers: {
         Accept: 'application/json',
         'Content-Type': 'application/json',
         ...options.headers,
       },
     })
   } catch {
     throw new Error('No fue posible conectar con el servidor. Verifica tu conexión e inténtalo de nuevo.')
   }

   if (!response.ok) {
     if (response.status === 401) throw new ApiError(401, 'Usuario o contraseña incorrectos.')
     if (response.status === 403) throw new ApiError(403, 'No tienes permiso para consultar esta información.')
     if (response.status === 429) throw new ApiError(429, 'Demasiados intentos. Espera un momento e inténtalo de nuevo.')
     if (response.status === 422) throw new ApiError(422, 'Revisa los datos ingresados e inténtalo de nuevo.')
     throw new ApiError(response.status, 'Ocurrió un error en el servidor. Inténtalo de nuevo.')
   }

   try {
     return await response.json() as T
   } catch {
     throw new Error('El servidor devolvió una respuesta inválida.')
   }
 }

