 import { useEffect, useState } from 'react'
 import type { ReactNode } from 'react'
 import { ApiError, request } from './api'
 import type { User } from './api'
 import UserManagement from './UserManagement'
 import LocationManagement from './LocationManagement'
 import './Workspace.css'

 type Branch = { id: number; name: string; code: string; address: string | null; is_active: boolean; municipality: { name: string; department: { name: string } } | null }
 type Register = { id: number; name: string; code: string; is_active: boolean; branch: { name: string } }
 type Account = { id: number; name: string; type: string; is_active: boolean; branch: { name: string } }
 type Section = 'inicio' | 'sucursales' | 'cajas' | 'cuentas' | 'usuarios' | 'ubicaciones'
 type Resource<T> =
   | { status: 'loading' }
   | { status: 'ready'; data: T[] }
   | { status: 'error'; message: string }

 const labels: Record<Section, string> = {
   inicio: 'Inicio',
   sucursales: 'Sucursales',
   cajas: 'Cajas',
   cuentas: 'Cuentas',
   usuarios: 'Usuarios',
   ubicaciones: 'Ubicaciones',
 }

 const accountTypes: Record<string, string> = {
   caja_mayor: 'Caja mayor',
   caja_menor: 'Caja menor',
   banco: 'Banco',
   qr: 'QR',
 }

 function useResource<T>(path: string, token: string, enabled: boolean, onSessionExpired: () => void) {
   const [resource, setResource] = useState<Resource<T>>({ status: 'loading' })
   const [retry, setRetry] = useState(0)

   useEffect(() => {
     if (!enabled) return
     let active = true
     request<unknown>(path, { headers: { Authorization: `Bearer ${token}` } })
       .then((result) => {
         if (!Array.isArray(result)) throw new Error('El servidor devolvió una respuesta inválida.')
         if (active) setResource({ status: 'ready', data: result as T[] })
       })
       .catch((error: unknown) => {
         if (!active) return
         if (error instanceof ApiError && error.status === 401) {
           onSessionExpired()
         } else {
           setResource({ status: 'error', message: error instanceof Error ? error.message : 'No se pudieron cargar los datos.' })
         }
       })
     return () => { active = false }
   }, [path, token, enabled, onSessionExpired, retry])

   function reload() {
     setResource((previous) => previous.status === 'ready' ? previous : { status: 'loading' })
     setRetry((previous) => previous + 1)
   }

   return { resource, reload }
 }

 function ResourceView<T>({ resource, reload, empty, render }: {
   resource: Resource<T>
   reload: () => void
   empty: string
   render: (item: T) => ReactNode
 }) {
   if (resource.status === 'loading') return <p className="workspace-message" role="status">Cargando información...</p>
   if (resource.status === 'error') {
     return <div className="resource-error" role="alert"><p>{resource.message}</p><button type="button" onClick={reload}>Reintentar</button></div>
   }
   if (resource.data.length === 0) return <p className="workspace-message">{empty}</p>
   return <div className="record-list">{resource.data.map(render)}</div>
 }

 function RecordRow({ title, detail, status }: { title: string; detail: string; status?: boolean }) {
   return (
     <div className="record-row">
       <div className="record-symbol" aria-hidden="true">▦</div>
       <div className="record-copy"><strong>{title}</strong><span>{detail}</span></div>
       {status !== undefined && <span className={`record-status ${status ? 'active' : 'inactive'}`}>{status ? 'Activa' : 'Inactiva'}</span>}
     </div>
   )
 }

 function Workspace({ token, user, onUserUpdated, onSessionExpired, onLogout, logoutBusy, logoutError }: {
   token: string
   user: User
   onUserUpdated: (user: User) => void
   onSessionExpired: () => void
   onLogout: () => void
   logoutBusy: boolean
   logoutError: string
 }) {
   const [section, setSection] = useState<Section>('inicio')
   const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
   const [settingsOpen, setSettingsOpen] = useState(false)
   const isAdmin = user.roles.includes('admin')
   const canViewAccounts = isAdmin || user.roles.includes('supervisor')
   const branches = useResource<Branch>('/branches', token, true, onSessionExpired)
   const registers = useResource<Register>('/registers', token, true, onSessionExpired)
   const accounts = useResource<Account>('/accounts', token, canViewAccounts, onSessionExpired)
   const users = useResource<User>('/users', token, isAdmin, onSessionExpired)
   const sections: Section[] = ['inicio', 'sucursales', 'cajas']
   if (canViewAccounts) sections.push('cuentas')
   if (isAdmin) sections.push('usuarios')

   const summaries = [
     { section: 'sucursales' as const, description: 'Puntos del negocio', resource: branches.resource },
     { section: 'cajas' as const, description: 'Cajas registradas', resource: registers.resource },
     ...(canViewAccounts ? [{ section: 'cuentas' as const, description: 'Medios y fondos', resource: accounts.resource }] : []),
     ...(isAdmin ? [{ section: 'usuarios' as const, description: 'Personas con acceso', resource: users.resource }] : []),
   ]

   return (
     <div className={`workspace${sidebarCollapsed ? ' sidebar-collapsed' : ''}`}>
       <aside className="workspace-sidebar">
         <div className="workspace-sidebar-top">
           <div className="workspace-brand"><span className="workspace-brand-mark">$</span><span className="workspace-brand-name">Cuadre<span>Caja</span></span></div>
           <button
             className="sidebar-toggle"
             type="button"
             aria-label={sidebarCollapsed ? 'Expandir menú lateral' : 'Contraer menú lateral'}
             aria-expanded={!sidebarCollapsed}
             aria-controls="workspace-navigation"
             onClick={() => setSidebarCollapsed((collapsed) => !collapsed)}
           >
             <svg aria-hidden="true" viewBox="0 0 24 24" fill="none">
               <path d="m14 6-6 6 6 6" />
             </svg>
           </button>
         </div>
         <p className="sidebar-label">ESPACIO DE TRABAJO</p>
         <nav className="workspace-nav" id="workspace-navigation" aria-label="Navegación principal">
           {sections.map((item) => (
             <button type="button" key={item} title={labels[item]} aria-label={labels[item]} className={section === item ? 'selected' : ''} aria-current={section === item ? 'page' : undefined} onClick={() => setSection(item)}>
               <span className="nav-icon" aria-hidden="true">{item === 'inicio' ? '⌂' : item === 'sucursales' ? '▦' : item === 'cajas' ? '▣' : item === 'cuentas' ? '◈' : '♙'}</span>
               <span className="nav-label">{labels[item]}</span>
             </button>
           ))}
           {isAdmin && (
             <div className="nav-group">
               <button type="button" className={section === 'ubicaciones' ? 'nav-group-active' : ''} title="Configuración" aria-label="Configuración" aria-expanded={settingsOpen} aria-controls="settings-navigation" onClick={() => {
                 if (sidebarCollapsed) {
                   setSidebarCollapsed(false)
                   setSettingsOpen(true)
                 } else {
                   setSettingsOpen((open) => !open)
                 }
               }}>
                 <span className="nav-icon" aria-hidden="true">⚙</span>
                 <span className="nav-label">Configuración</span>
                 <span className={`nav-chevron${settingsOpen ? ' open' : ''}`} aria-hidden="true">⌄</span>
               </button>
               <div className="nav-submenu" id="settings-navigation" hidden={!settingsOpen}>
                 <button type="button" title="Ubicaciones" aria-label="Ubicaciones" className={section === 'ubicaciones' ? 'selected' : ''} aria-current={section === 'ubicaciones' ? 'page' : undefined} onClick={() => setSection('ubicaciones')}>
                   <span className="nav-icon" aria-hidden="true">⌖</span>
                   <span className="nav-label">Ubicaciones</span>
                 </button>
               </div>
             </div>
           )}
         </nav>
         <div className="sidebar-bottom"><span className="sidebar-dot" /> Tu negocio, en orden</div>
       </aside>

       <div className="workspace-body">
         <header className="workspace-header">
           <div><span className="header-overline">MI ESPACIO</span><strong>{labels[section]}</strong></div>
           <div className="header-actions">
             <div className="header-user"><span className="user-avatar">{user.name.charAt(0).toUpperCase()}</span><div><strong>{user.name}</strong><span>{user.roles.join(' · ') || 'Usuario'}</span></div></div>
             <button className="logout-button" type="button" disabled={logoutBusy} onClick={onLogout}>{logoutBusy ? 'Cerrando...' : 'Cerrar sesión'}</button>
           </div>
         </header>

         <main className="workspace-content">
           {logoutError && <p className="error" role="alert">{logoutError}</p>}
           {section === 'inicio' ? (
             <>
               <div className="welcome-panel">
                 <div><span className="welcome-kicker">TU ESPACIO DE TRABAJO</span><h1>¡Hola, {user.name}!</h1><p>Consulta la información disponible de tu negocio desde un solo lugar.</p></div>
                 <span className="welcome-symbol" aria-hidden="true">$</span>
               </div>
               <div className="section-heading"><div><span className="workspace-kicker">UN VISTAZO GENERAL</span><h2>Tu organización</h2><p>Información disponible según tus permisos.</p></div></div>
               <div className="summary-grid">
                 {summaries.map(({ section: item, description, resource }) => (
                   <button className="summary-card" key={item} type="button" onClick={() => setSection(item)}>
                     <span className="summary-icon" aria-hidden="true">{item === 'sucursales' ? '▦' : item === 'cajas' ? '▣' : item === 'cuentas' ? '◈' : '♙'}</span>
                     <span className="summary-title">{labels[item]}</span>
                     <strong>{resource.status === 'ready' ? resource.data.length : resource.status === 'loading' ? '…' : '—'}</strong>
                     <span className="summary-description">{resource.status === 'error' ? 'No se pudo cargar' : description}</span>
                     <span className="summary-link">Ver detalle <span aria-hidden="true">→</span></span>
                   </button>
                 ))}
               </div>
               <div className="coming-panel"><span className="coming-icon" aria-hidden="true">✦</span><div><strong>Seguimos construyendo tu espacio</strong><p>El registro de ventas, gastos y los cuadres diarios se incorporarán en la siguiente fase.</p></div></div>
             </>
           ) : (
             <>
               <div className="section-heading"><div><span className="workspace-kicker">{section === 'ubicaciones' ? 'CONFIGURACIÓN' : 'MI ORGANIZACIÓN'}</span><h1>{labels[section]}</h1><p>{section === 'usuarios' ? 'Gestiona los usuarios y sus permisos.' : section === 'ubicaciones' ? 'Administra los departamentos y municipios.' : 'Consulta la información disponible para tu usuario.'}</p></div></div>
               <section className="records-panel" aria-label={`Listado de ${labels[section].toLowerCase()}`}>
                 <div className="records-heading"><h2>{section === 'ubicaciones' ? 'Ubicaciones' : `Listado de ${labels[section].toLowerCase()}`}</h2>{section !== 'usuarios' && section !== 'ubicaciones' && <span>Solo consulta</span>}</div>
                 {section === 'sucursales' && <ResourceView resource={branches.resource} reload={branches.reload} empty="No hay sucursales disponibles para tu usuario." render={(branch) => <RecordRow key={branch.id} title={branch.name} detail={[branch.code, branch.municipality?.name, branch.municipality?.department.name, branch.address].filter(Boolean).join(' · ')} status={branch.is_active} />} />}
                 {section === 'cajas' && <ResourceView resource={registers.resource} reload={registers.reload} empty="No hay cajas disponibles para tu usuario." render={(register) => <RecordRow key={register.id} title={register.name} detail={`${register.code} · ${register.branch.name}`} status={register.is_active} />} />}
                 {section === 'cuentas' && canViewAccounts && <ResourceView resource={accounts.resource} reload={accounts.reload} empty="No hay cuentas disponibles para tu usuario." render={(account) => <RecordRow key={account.id} title={account.name} detail={`${accountTypes[account.type] ?? account.type} · ${account.branch.name}`} status={account.is_active} />} />}
                 {section === 'usuarios' && isAdmin && (users.resource.status === 'ready'
                   ? <UserManagement token={token} currentUser={user} users={users.resource.data} onSaved={users.reload} onSessionExpired={onSessionExpired} onUserUpdated={(updated) => { if (!updated.roles.includes('admin')) setSection('inicio'); onUserUpdated(updated) }} />
                   : <ResourceView resource={users.resource} reload={users.reload} empty="No hay usuarios registrados." render={() => null} />)}
                 {section === 'ubicaciones' && isAdmin && <LocationManagement token={token} onSessionExpired={onSessionExpired} />}
               </section>
             </>
           )}
         </main>
         <footer className="workspace-footer">CuadreCaja <span>·</span> Un espacio para tu negocio</footer>
       </div>
     </div>
   )
 }

 export default Workspace

