   .header-user > div { display: none; }
   .workspace-content { padding: 24px 6% 36px; }
   .welcome-panel { min-height: 165px; padding: 24px; }
   .welcome-symbol { width: 58px; height: 58px; border-radius: 18px; font-size: 36px; }
   .summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
