 namespace App\Http\Controllers\Api;

 use App\Http\Controllers\Controller;
 use App\Models\Account;
 use Illuminate\Http\JsonResponse;
 use Illuminate\Http\Request;
 use Illuminate\Validation\Rule;

 class AccountController extends Controller
 {
     private const TYPES = ['caja_mayor', 'caja_menor', 'banco', 'qr'];

     public function index(Request $request): JsonResponse
     {
         $user = $request->user();
         $branchIds = $user->hasRole('admin')
             ? null
             : ($user->hasRole('supervisor') ? $user->accessibleBranchIds() : []);

         $accounts = Account::query()
             ->when($branchIds !== null, fn ($query) => $query->whereIn('branch_id', $branchIds))
             ->with('branch:id,name,code')
             ->when($request->integer('branch_id'), fn ($query, $branchId) => $query->where('branch_id', $branchId))
             ->orderBy('name')
             ->get();

         return response()->json($accounts);
     }

     public function store(Request $request): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'branch_id' => ['required', 'integer', 'exists:branches,id'],
             'name' => ['required', 'string', 'max:255'],
             'type' => ['required', 'string', Rule::in(self::TYPES)],
             'is_active' => ['sometimes', 'boolean'],
         ]);

         return response()->json(Account::create($data)->load('branch:id,name,code'), 201);
     }

     public function show(Request $request, Account $account): JsonResponse
     {
         $this->ensureBranchAccess($request, $account->branch_id);

         return response()->json($account->load('branch:id,name,code'));
     }

     public function update(Request $request, Account $account): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'branch_id' => ['sometimes', 'required', 'integer', 'exists:branches,id'],
             'name' => ['sometimes', 'required', 'string', 'max:255'],
             'type' => ['sometimes', 'required', 'string', Rule::in(self::TYPES)],
             'is_active' => ['sometimes', 'boolean'],
         ]);

         $account->update($data);

         return response()->json($account->load('branch:id,name,code'));
     }

     private function ensureAdmin(Request $request): void
     {
         abort_unless($request->user()->hasRole('admin'), 403, 'Se requiere el rol admin.');
     }

     private function ensureBranchAccess(Request $request, int $branchId): void
     {
         abort_unless(
             $request->user()->hasRole('admin')
                 || ($request->user()->hasRole('supervisor') && in_array($branchId, $request->user()->accessibleBranchIds())),
             403,
             'No tienes acceso a esta sucursal.',
         );
     }
 }

