 use Illuminate\Foundation\Testing\RefreshDatabase;
 use Tests\TestCase;

 class PhaseOneApiTest extends TestCase
 {
     use RefreshDatabase;

     protected function setUp(): void
     {
         parent::setUp();

         $this->seed(RoleSeeder::class);
     }

     public function test_login_returns_a_token_that_can_access_the_profile(): void
     {
         $user = User::factory()->create(['password' => 'correct-password']);
         $user->assignRole('admin');

         $response = $this->postJson('/api/login', [
             'username' => strtoupper($user->username),
             'password' => 'correct-password',
         ]);

         $response->assertOk()
             ->assertJsonPath('user.roles.0', 'admin')
             ->assertJsonStructure(['token', 'user' => ['id', 'name', 'username', 'email', 'roles']]);

         $this->withToken($response->json('token'))
             ->getJson('/api/user')
             ->assertOk()
             ->assertJsonPath('id', $user->id);
     }

     public function test_invalid_login_is_rejected(): void
     {
         $user = User::factory()->create(['password' => 'correct-password']);

         $this->postJson('/api/login', [
