         $supervisor->assignRole('supervisor');
         $cashier = User::factory()->create();
         $cashier->assignRole('cajero');

         $response = $this->actingAs($admin, 'sanctum')->postJson('/api/branches', [
             'name' => 'Centro', 'code' => 'CTR', 'address' => 'Calle 1', 'user_ids' => [$supervisor->id],
         ])->assertCreated()->assertJsonPath('is_active', true)->assertJsonPath('users.0.id', $supervisor->id);
         $id = $response->json('id');

         $this->postJson('/api/branches', ['name' => 'Duplicada', 'code' => 'CTR'])->assertUnprocessable()->assertJsonValidationErrors('code');
         $this->putJson("/api/branches/{$id}", ['name' => 'Centro nuevo', 'user_ids' => [$cashier->id]])
             ->assertOk()->assertJsonPath('name', 'Centro nuevo')->assertJsonPath('users.0.id', $cashier->id);
         $this->assertDatabaseMissing('branch_user', ['branch_id' => $id, 'user_id' => $supervisor->id]);
