 namespace App\Http\Controllers\Api;

 use App\Http\Controllers\Controller;
 use App\Models\Branch;
 use Illuminate\Database\Query\Builder;
 use Illuminate\Http\JsonResponse;
 use Illuminate\Http\Request;
 use Illuminate\Support\Facades\DB;
 use Illuminate\Validation\Rule;
 use Illuminate\Validation\Rules\Exists;
 use Spatie\Permission\Models\Role;

 class BranchController extends Controller
 {
     private const VALIDATION_MESSAGES = [
         'name.required' => 'El nombre de la sucursal es obligatorio.',
         'code.required' => 'El código de la sucursal es obligatorio.',
         'code.unique' => 'Ya existe una sucursal con este código.',
         'municipality_code.exists' => 'El municipio no existe o su ubicación está inactiva.',
         'roles.*.in' => 'El rol seleccionado no es válido.',
         'user_ids.missing' => 'La asignación de usuarios a sucursales ya no está disponible; usa roles.',
     ];

     public function index(Request $request): JsonResponse
     {
         $query = Branch::query()
             ->when(! $request->user()->hasRole('admin'), fn ($query) => $query->whereIn('id', $request->user()->accessibleBranchIds()))
             ->with('municipality.department')
             ->orderBy('name');

         if ($request->user()->hasRole('admin')) {
             $query->with('roles:id,name');
         }

         return response()->json($query->get());
     }

     public function store(Request $request): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'name' => ['required', 'string', 'max:255'],
             'code' => ['required', 'string', 'max:255', 'unique:branches,code'],
             'address' => ['nullable', 'string', 'max:255'],
             'municipality_code' => ['nullable', 'string', 'size:5', $this->activeMunicipalityRule()],
             'is_active' => ['sometimes', 'boolean'],
             'roles' => ['sometimes', 'array'],
             'roles.*' => ['required', 'string', 'distinct', Rule::in(['supervisor', 'cajero'])],
             'user_ids' => ['missing'],
         ], self::VALIDATION_MESSAGES);

         $roles = $data['roles'] ?? [];
         unset($data['roles']);

         $branch = DB::transaction(function () use ($data, $roles) {
             $branch = Branch::create($data);
             $branch->roles()->sync($this->roleIds($roles));

             return $branch;
         });

         return response()->json($branch->load('roles:id,name', 'municipality.department'), 201);
     }

     public function show(Request $request, Branch $branch): JsonResponse
     {
         $this->ensureBranchAccess($request, $branch);

         if ($request->user()->hasRole('admin')) {
             return response()->json($branch->load('roles:id,name', 'accounts', 'cashRegisters', 'municipality.department'));
         }
         if (in_array($branch->id, $request->user()->accessibleBranchIds('supervisor'))) {
             return response()->json($branch->load('accounts', 'cashRegisters', 'municipality.department'));
         }

         $cashRegisters = $branch->cashRegisters()
             ->whereHas('users', fn ($query) => $query->whereKey($request->user()->id))
             ->get();

         $branch->load('municipality.department');

         return response()->json($branch->only(['id', 'name', 'code', 'address', 'municipality_code', 'is_active']) + [
             'municipality' => $branch->municipality,
             'cash_registers' => $cashRegisters,
         ]);
     }

     public function update(Request $request, Branch $branch): JsonResponse
     {
         $this->ensureAdmin($request);
         $data = $request->validate([
             'name' => ['sometimes', 'required', 'string', 'max:255'],
             'code' => ['sometimes', 'required', 'string', 'max:255', Rule::unique('branches', 'code')->ignore($branch->id)],
             'address' => ['sometimes', 'nullable', 'string', 'max:255'],
             'municipality_code' => [
                 'sometimes', 'nullable', 'string', 'size:5',
                 $request->input('municipality_code') === $branch->municipality_code
                     ? Rule::exists('municipalities', 'code')
                     : $this->activeMunicipalityRule(),
             ],
             'is_active' => ['sometimes', 'boolean'],
             'roles' => ['sometimes', 'array'],
             'roles.*' => ['required', 'string', 'distinct', Rule::in(['supervisor', 'cajero'])],
             'user_ids' => ['missing'],
         ], self::VALIDATION_MESSAGES);

         DB::transaction(function () use ($branch, $data) {
             if (array_key_exists('roles', $data)) {
                 $branch->roles()->sync($this->roleIds($data['roles']));
                 unset($data['roles']);
             }

             $branch->update($data);
         });

         return response()->json($branch->load('roles:id,name', 'municipality.department'));
     }

     private function roleIds(array $roles): array
     {
         $ids = Role::query()->where('guard_name', 'web')->whereIn('name', $roles)->pluck('id')->all();
         if (count($ids) !== count($roles)) {
             throw new \RuntimeException('Faltan roles requeridos. Ejecuta RoleSeeder.');
         }

         return $ids;
     }

     private function ensureAdmin(Request $request): void
     {
         abort_unless($request->user()->hasRole('admin'), 403, 'Se requiere el rol admin.');
     }

     private function activeMunicipalityRule(): Exists
     {
         return Rule::exists('municipalities', 'code')->where(
             fn (Builder $query) => $query->where('is_active', true)
                 ->whereIn('department_code', DB::table('departments')->where('is_active', true)->select('code')),
         );
     }

     private function ensureBranchAccess(Request $request, Branch $branch): void
     {
         abort_unless(
             $request->user()->hasRole('admin') || in_array($branch->id, $request->user()->accessibleBranchIds()),
             403,
             'No tienes acceso a esta sucursal.',
         );
     }
 }

