         ], ['branch_id.exists' => 'La sucursal no existe o está inactiva.']);

         $account->update($data);

         return response()->json($account->load('branch:id,name,code'));
     }

     private function ensureAdmin(Request $request): void
     {
         abort_unless($request->user()->hasRole('admin'), 403, 'Se requiere el rol admin.');
     }

     private function ensureBranchAccess(Request $request, int $branchId): void
     {
         abort_unless(
             $request->user()->hasRole('admin')
                 || in_array($branchId, $request->user()->accessibleBranchIds('supervisor')),
             403,
             'No tienes acceso a esta sucursal.',
         );
     }
 }

