 namespace App\Models;

 // use Illuminate\Contracts\Auth\MustVerifyEmail;
 use Database\Factories\UserFactory;
 use App\Support\Access;
 use Illuminate\Database\Eloquent\Attributes\Fillable;
 use Illuminate\Database\Eloquent\Attributes\Hidden;
 use Illuminate\Database\Eloquent\Factories\HasFactory;
 use Illuminate\Database\Eloquent\Relations\BelongsToMany;
 use Illuminate\Foundation\Auth\User as Authenticatable;
 use Illuminate\Notifications\Notifiable;
 use Laravel\Sanctum\HasApiTokens;
 use Spatie\Permission\Traits\HasRoles;

 #[Fillable(['name', 'username', 'email', 'password', 'is_active'])]
 #[Hidden(['password', 'remember_token'])]
 class User extends Authenticatable
 {
     /** @use HasFactory<UserFactory> */
     use HasApiTokens, HasFactory, HasRoles, Notifiable;

     protected $attributes = ['is_active' => true];

     public function branches(): BelongsToMany
     {
         return $this->belongsToMany(Branch::class)->withTimestamps();
     }

     public function cashRegisters(): BelongsToMany
     {
         return $this->belongsToMany(CashRegister::class)->withTimestamps();
     }

     public function accessibleBranchIds(?string $role = null): array
     {
         if ($this->hasRole('admin')) {
             return Branch::query()->pluck('id')->all();
         }

         public function permissionNames(): array
         {
             if ($this->hasRole('admin')) {
                 return array_keys(Access::GLOBAL + Access::BRANCH);
             }

             return $this->getAllPermissions()->pluck('name')->unique()->values()->all();
         }

         $roles = $this->getRoleNames();
         if ($role !== null) {
             $roles = $roles->filter(fn ($name) => $name === $role);
         }

         return Branch::query()->whereHas('roles', fn ($query) => $query
             ->where('guard_name', 'web')->whereIn('name', $roles->all()))->pluck('id')->all();
     }

     /**
      * Get the attributes that should be cast.
      *
      * @return array<string, string>
      */
     protected function casts(): array
     {
         return [
             'email_verified_at' => 'datetime',
             'password' => 'hashed',
             'is_active' => 'boolean',
         ];
     }
 }

