           expireSession()
         } else {
           setError(err instanceof Error ? err.message : 'No se pudo verificar la sesión.')
         }
         setChecking(false)
       })
     return () => { active = false }
   }, [token, retry, expireSession])

   async function handleLogin(event: FormEvent<HTMLFormElement>) {
     event.preventDefault()
     setError('')
     setBusy(true)
     try {
       const result = await request<{ token: string; user: User }>('/login', {
         method: 'POST',
         body: JSON.stringify({ username: username.trim(), password }),
       })
       sessionStorage.setItem(tokenKey, result.token)
       setChecking(true)
       setToken(result.token)
       setPassword('')
     } catch (err) {
       setError(err instanceof Error ? err.message : 'No se pudo iniciar sesión.')
     } finally {
       setBusy(false)
     }
   }

   async function handleLogout() {
     if (!token) return
     setBusy(true)
     setError('')
     try {
       await request('/logout', {
         method: 'POST',
         headers: { Authorization: `Bearer ${token}` },
       })
       sessionStorage.removeItem(tokenKey)
       setToken(null)
       setUser(null)
     } catch (err) {
       if (err instanceof ApiError && err.status === 401) {
         expireSession()
       } else {
         setError(err instanceof Error ? err.message : 'No se pudo cerrar sesión.')
       }
     } finally {
       setBusy(false)
     }
   }

   if (token && user && !checking) {
     return <Workspace token={token} user={user} onUserUpdated={setUser} onSessionExpired={expireSession} onLogout={handleLogout} logoutBusy={busy} logoutError={error} />
   }

   return (
     <div className="page-shell">
       <header className="topbar">
         <div className="brand">
           <span className="brand-mark" aria-hidden="true">$</span>
           <span>Cuadre<span className="brand-accent">Caja</span></span>
         </div>
         <span className="topbar-label"><span className="status-dot" /> Tu espacio financiero</span>
       </header>

       <main className="layout">
